import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Day 15: Devshell Debugging","description":"","frontmatter":{},"headers":[],"relativePath":"day15-cmake-recipes-and-devshell-debugging.md","filePath":"day15-cmake-recipes-and-devshell-debugging.md"}'),o={name:"day15-cmake-recipes-and-devshell-debugging.md"};function s(n,e,d,r,c,h){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="day-15-devshell-debugging" tabindex="-1">Day 15: Devshell Debugging <a class="header-anchor" href="#day-15-devshell-debugging" aria-label="Permalink to &quot;Day 15: Devshell Debugging&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Explain the purpose of the <code>devshell</code> task in BitBake</li><li>Open an interactive cross-compilation terminal for any recipe</li><li>Manually execute configuration and compilation steps to debug complex failures</li><li>Rapidly iterate on C/C++ code without running full BitBake cycles</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day14-autotools-and-cmake-build-systems.html">Day 14: Autotools &amp; CMake Build Systems</a></li></ul></div><hr><h2 id="_1-the-debugging-dilemma" tabindex="-1">1. The Debugging Dilemma <a class="header-anchor" href="#_1-the-debugging-dilemma" aria-label="Permalink to &quot;1. The Debugging Dilemma&quot;">​</a></h2><p>When writing recipes for complex C/C++ projects, things often break during <code>do_configure</code> or <code>do_compile</code>.</p><p>The traditional debugging loop is slow and painful:</p><ol><li>Run <code>bitbake myrecipe</code></li><li>Build fails.</li><li>Hunt down <code>log.do_compile</code> in the <code>tmp/work/...</code> directory.</li><li>Read the log, guess the fix, modify the recipe or <code>.patch</code> file.</li><li>Run <code>bitbake -c clean myrecipe</code></li><li>Run <code>bitbake myrecipe</code> again and wait for it to unpack and configure all over again.</li></ol><p>There is a vastly superior way to debug: <strong>The Developer Shell (<code>devshell</code>)</strong>.</p><hr><h2 id="_2-introducing-bitbake-c-devshell" tabindex="-1">2. Introducing <code>bitbake -c devshell</code> <a class="header-anchor" href="#_2-introducing-bitbake-c-devshell" aria-label="Permalink to &quot;2. Introducing `bitbake -c devshell`&quot;">​</a></h2><p>The <code>devshell</code> task pauses the BitBake build process immediately after <code>do_patch</code> (source code is unpacked and patched) and before <code>do_configure</code>.</p><p>It then opens a brand new terminal window on your host machine.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devshell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myrecipe</span></span></code></pre></div><h3 id="what-makes-the-devshell-special" tabindex="-1">What makes the Devshell special? <a class="header-anchor" href="#what-makes-the-devshell-special" aria-label="Permalink to &quot;What makes the Devshell special?&quot;">​</a></h3><p>This isn&#39;t a normal terminal. BitBake has meticulously injected <strong>hundreds of cross-compilation environment variables</strong> into this shell.</p><ul><li>The <code>CC</code> variable points to the Yocto cross-compiler, not your host&#39;s GCC.</li><li>The <code>CFLAGS</code> and <code>LDFLAGS</code> are fully populated.</li><li>The <code>PATH</code> is prepended with Yocto&#39;s native tools.</li><li>The <code>PKG_CONFIG_PATH</code> points to the <code>recipe-sysroot</code>, not your host&#39;s <code>/usr/lib</code>.</li></ul><p>You are effectively standing inside the matrix. If you type <code>make</code>, it will cross-compile for the target architecture (e.g., ARM) perfectly.</p><hr><h2 id="_3-interactive-debugging-workflow" tabindex="-1">3. Interactive Debugging Workflow <a class="header-anchor" href="#_3-interactive-debugging-workflow" aria-label="Permalink to &quot;3. Interactive Debugging Workflow&quot;">​</a></h2><p>Once the Devshell terminal pops open, you are placed directly inside the recipe&#39;s source directory (<code>${S}</code>).</p><p>Here is how you use it to debug a broken build:</p><h3 id="step-1-manually-configure" tabindex="-1">Step 1: Manually Configure <a class="header-anchor" href="#step-1-manually-configure" aria-label="Permalink to &quot;Step 1: Manually Configure&quot;">​</a></h3><p>If the recipe inherits Autotools, manually run the configure script to see exactly why it is failing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ${EXTRA_OECONF}</span></span></code></pre></div><h3 id="step-2-manually-compile" tabindex="-1">Step 2: Manually Compile <a class="header-anchor" href="#step-2-manually-compile" aria-label="Permalink to &quot;Step 2: Manually Compile&quot;">​</a></h3><p>If the configuration succeeds, run <code>make</code> manually.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j8</span></span></code></pre></div><p>Since you are in an interactive terminal, if <code>make</code> fails with a C syntax error, you can use <code>vim</code> or <code>nano</code> right there in the terminal to edit the source code (<code>.c</code> file) and immediately run <code>make</code> again.</p><h3 id="step-3-capture-the-fix" tabindex="-1">Step 3: Capture the Fix <a class="header-anchor" href="#step-3-capture-the-fix" aria-label="Permalink to &quot;Step 3: Capture the Fix&quot;">​</a></h3><p>Once you successfully compile the code in the devshell, you know exactly what changes were required.</p><ol><li>Use <code>git diff</code> inside the devshell to see what C code you changed.</li><li>Save that diff as a <code>.patch</code> file (as learned in Day 10).</li><li>Exit the devshell (type <code>exit</code> or <code>Ctrl+D</code>).</li><li>Add the <code>.patch</code> to your recipe&#39;s <code>SRC_URI</code>.</li><li>Run a clean BitBake build to verify.</li></ol><hr><h2 id="_4-troubleshooting-devshell-terminals" tabindex="-1">4. Troubleshooting Devshell Terminals <a class="header-anchor" href="#_4-troubleshooting-devshell-terminals" aria-label="Permalink to &quot;4. Troubleshooting Devshell Terminals&quot;">​</a></h2><p>By default, BitBake tries to spawn the devshell using <code>xterm</code> or <code>gnome-terminal</code>. If you are running Yocto inside a headless server, a Docker container, or over SSH without X11 forwarding, the devshell will fail to open.</p><h3 id="the-headless-fallback-tmux" tabindex="-1">The Headless Fallback: <code>tmux</code> <a class="header-anchor" href="#the-headless-fallback-tmux" aria-label="Permalink to &quot;The Headless Fallback: `tmux`&quot;">​</a></h3><p>You can force BitBake to use <code>tmux</code> (a terminal multiplexer) instead of a graphical terminal window. This works perfectly over SSH.</p><p>Install <code>tmux</code> on your host:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tmux</span></span></code></pre></div><p>Tell BitBake to use it in your <code>conf/local.conf</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">OE_TERMINAL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tmux&quot;</span></span></code></pre></div><p>Now, when you run <code>bitbake -c devshell myrecipe</code>, a tmux session will take over your current terminal window.</p><hr><h2 id="_5-hands-on-lab-exercises" tabindex="-1">5. Hands-On Lab Exercises <a class="header-anchor" href="#_5-hands-on-lab-exercises" aria-label="Permalink to &quot;5. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 15.1: Explore the Matrix</p><ol><li>Run <code>bitbake -c devshell busybox</code>.</li><li>A new terminal will appear (or tmux session).</li><li>Type <code>echo $CC</code> to see the cross-compiler binary.</li><li>Type <code>env | grep SYSROOT</code> to see how the environment isolates the build.</li><li>Type <code>exit</code> to close the devshell.</li></ol></div><hr><h2 id="_6-further-reading" tabindex="-1">6. Further Reading <a class="header-anchor" href="#_6-further-reading" aria-label="Permalink to &quot;6. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Using a Development Shell</td><td><a href="https://docs.yoctoproject.org/dev-manual/development-shell.html" target="_blank" rel="noreferrer">docs.yoctoproject.org/dev-manual/development-shell.html</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day14-autotools-and-cmake-build-systems">← Day 14: Autotools &amp; CMake</a><a href="/day16-filespath-splashscreen-and-bbappends">Day 16: BBAppends &amp; Splash Screen →</a></div>',50)])])}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
